fn unique_id(prefix: &str) -> String {
    let mut bytes = [0_u8; 8];
    getrandom::getrandom(&mut bytes).expect("the OS random source should be available");
    let suffix: String = bytes.iter().map(|byte| format!("{byte:02x}")).collect();
    format!("{prefix}-{suffix}")
}

async fn enroll_repository(database_url: &str, tenant_id: &str, repository_id: &str, unique: &str) {
    let seed: [u8; 32] = Sha256::digest(format!("key-{unique}").as_bytes()).into();
    let signing_key = SigningKey::from_bytes(&seed);
    let public_key = signing_key.verifying_key().to_bytes();
    let request_id = format!("request-{unique}");
    let node_id = format!("node-{unique}");
    let fingerprint = public_key_fingerprint(&public_key);
    let submission = EnrollmentSubmission {
        request_id: request_id.clone(),
        tenant_id: tenant_id.to_string(),
        repository_id: repository_id.to_string(),
        proposed_node_id: node_id.clone(),
        display_name: "Work API integration node".to_string(),
        public_key: public_key.to_vec(),
        public_key_fingerprint: fingerprint.clone(),
        requested_capabilities: vec!["synchronize".to_string()],
        created_at: "2026-01-01T00:00:00Z".to_string(),
        expires_at: "2030-01-01T00:00:00Z".to_string(),
    };
    let request = ActivationChallengeRequest {
        request_id,
        tenant_id: tenant_id.to_string(),
        repository_id: repository_id.to_string(),
        proposed_node_id: node_id,
        public_key_fingerprint: fingerprint,
    };
    let mut enrollment = EnrollmentStore::connect(database_url)
        .await
        .expect("connect enrollment store");
    enrollment
        .submit(&submission)
        .await
        .expect("submit enrollment");
    enrollment
        .approve(&EnrollmentApproval {
            request_id: submission.request_id.clone(),
            tenant_id: tenant_id.to_string(),
            repository_id: repository_id.to_string(),
            public_key_fingerprint: submission.public_key_fingerprint.clone(),
            approved_capabilities: submission.requested_capabilities.clone(),
            approved_by: "work-api-integration-administrator".to_string(),
        })
        .await
        .expect("approve enrollment");
    let nonce: [u8; 32] = Sha256::digest(format!("nonce-{unique}").as_bytes()).into();
    let challenge = enrollment
        .issue_challenge(&request, &nonce, SystemTime::now())
        .await
        .expect("issue enrollment challenge");
    let signature = signing_key.sign(&activation_challenge_bytes(
        &challenge.nonce,
        &request.request_id,
        &request.tenant_id,
        &request.repository_id,
        &request.proposed_node_id,
        &request.public_key_fingerprint,
    ));
    enrollment
        .activate(
            &EnrollmentActivation {
                request,
                nonce: challenge.nonce,
                signature: signature.to_bytes().to_vec(),
            },
            &format!("receipt-{unique}"),
            &format!("signing-key-{unique}"),
            SystemTime::now(),
        )
        .await
        .expect("activate enrollment");
}

async fn application(database_url: &str, tenant_id: &str) -> axum::Router {
    let work = Arc::new(
        WorkStore::connect(database_url)
            .await
            .expect("connect Work store"),
    );
    let fleet = Arc::new({
        let pool = ackplane_server::db_pool::build_pool(
            database_url,
            ackplane_server::db_pool::TEST_POOL_MAX_SIZE,
        )
        .expect("the test pool builds from the gated database url");
        FleetStore::connect(&pool)
            .await
            .expect("connect Fleet store")
    });
    work_routes(WorkApiState::new(
        work,
        fleet,
        Arc::from(tenant_id.to_string()),
    ))
}

async fn body_json(response: axum::response::Response) -> Value {
    let body = to_bytes(response.into_body(), 1_048_576)
        .await
        .expect("read Bridge response body");
    serde_json::from_slice(&body).expect("parse Bridge JSON response")
}

#[tokio::test]
async fn work_list_and_board_doctor_report_a_real_task_and_an_orphan_claim() {
    let Ok(database_url) = std::env::var("ACKPLANE_TEST_DATABASE_URL") else {
        println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
        return;
    };
    let unique = unique_id("work-api");
    let tenant_id = format!("tenant-{unique}");
    let repository_id = format!("repository-{unique}");
    enroll_repository(&database_url, &tenant_id, &repository_id, &unique).await;

    let mut work_store = WorkStore::connect(&database_url)
        .await
        .expect("connect Work store for fixtures");
    let task_id = format!("task-{unique}");
    work_store
        .create_task(
            &NewWorkTask {
                tenant_id: tenant_id.clone(),
                repository_id: repository_id.clone(),
                task_id: task_id.clone(),
                title: "Ship the Work API".to_owned(),
                acceptance: "the Work API responds correctly".to_owned(),
                goal_id: None,
                declared_paths: Vec::new(),
                declared_symbols: Vec::new(),
                published_by: "work-api-integration".to_owned(),
            },
            &format!("event-{unique}"),
            SystemTime::now(),
        )
        .await
        .expect("create Work task fixture");

    let db_pool = ackplane_server::db_pool::build_pool(
        &database_url,
        ackplane_server::db_pool::TEST_POOL_MAX_SIZE,
    )
    .expect("the test pool builds from the gated database url");
    let claim_store = ClaimStore::connect(&db_pool)
        .await
        .expect("connect Claim store for fixtures");
    let orphan_task_id = format!("orphan-{unique}");
    let claim = claim_store
        .delegate(
            &ClaimLeaseRequest {
                tenant_id: tenant_id.clone(),
                repository_id: repository_id.clone(),
                task_id: orphan_task_id.clone(),
                owner_id: "owner-1".to_owned(),
                branch: "claims-only".to_owned(),
                lease: std::time::Duration::from_secs(3600),
                paths: vec!["crates/ackplane-bridge/src/work_api.rs".to_owned()],
                symbols: vec!["symbol:work-api".to_owned()],
            },
            SystemTime::now(),
        )
        .await
        .expect("delegate an orphan claim with no Work task");

    let app = application(&database_url, &tenant_id).await;

    let work_page = app
        .clone()
        .oneshot(
            Request::builder()
                .uri("/work")
                .body(Body::empty())
                .expect("build Work page request"),
        )
        .await
        .expect("serve Work page route");
    assert_eq!(work_page.status(), StatusCode::OK);

    let doctor_page = app
        .clone()
        .oneshot(
            Request::builder()
                .uri("/board-doctor")
                .body(Body::empty())
                .expect("build Board Doctor page request"),
        )
        .await
        .expect("serve Board Doctor page route");
    assert_eq!(doctor_page.status(), StatusCode::OK);

    let list = app
        .clone()
        .oneshot(
            Request::builder()
                .uri(format!("/api/v1/repositories/{repository_id}/work"))
                .body(Body::empty())
                .expect("build Work list request"),
        )
        .await
        .expect("serve Work list route");
    assert_eq!(list.status(), StatusCode::OK);
    let list = body_json(list).await;
    assert_eq!(list["total"], serde_json::json!(1));
    assert_eq!(list["items"][0]["task_id"], serde_json::json!(task_id));
    assert_eq!(list["items"][0]["state"], serde_json::json!("open"));
    // Regression: this list reported `authorization_unavailable` for all ten
    // operations while the command routes executed every one of them (see
    // `every_command_kind_records_a_pending_confirmation_under_the_verified_loopback_principal`
    // in work_command_api_integration.rs). The page told an operator the board
    // was read-only; the buttons worked. Deriving the expectation from
    // `WorkCommandKind::ALL` rather than typing ten rows means narrowing what
    // the principal grants fails this test until the page is narrowed too.
    let expected_commands: Vec<Value> = WorkCommandKind::ALL
        .iter()
        .map(|kind| {
            serde_json::json!({
                "operation": kind.operation_name(),
                "state": "available_without_policy",
                "reason": "The hardened loopback profile is a verified principal for this single-tenant deployment, so this command executes. No policy layer is adopted, so nothing classifies it as routine or requiring review.",
            })
        })
        .collect();
    assert_eq!(list["commands"], Value::Array(expected_commands));
    assert_eq!(
        list["publication"],
        serde_json::json!({
            "state": "current",
            "claims_only_total": 1,
            "claims_only": [{
                "task_id": orphan_task_id,
                "owner_id": "owner-1",
                "branch": "claims-only",
                "lease_expires_at_seconds": claim
                    .lease_expires_at
                    .duration_since(UNIX_EPOCH)
                    .expect("lease expiry is after the Unix epoch")
                    .as_secs(),
                "declared_paths": ["crates/ackplane-bridge/src/work_api.rs"],
                "declared_symbols": ["symbol:work-api"],
            }],
        })
    );

    let detail = app
        .clone()
        .oneshot(
            Request::builder()
                .uri(format!(
                    "/api/v1/repositories/{repository_id}/work/{task_id}"
                ))
                .body(Body::empty())
                .expect("build Work detail request"),
        )
        .await
        .expect("serve Work detail route");
    assert_eq!(detail.status(), StatusCode::OK);
    let detail = body_json(detail).await;
    assert_eq!(detail["task"]["task_id"], serde_json::json!(task_id));
    assert_eq!(
        detail["history"].as_array().expect("history array").len(),
        1
    );

    let doctor = app
        .clone()
        .oneshot(
            Request::builder()
                .uri(format!("/api/v1/repositories/{repository_id}/work/doctor"))
                .body(Body::empty())
                .expect("build Board Doctor request"),
        )
        .await
        .expect("serve Board Doctor route");
    assert_eq!(doctor.status(), StatusCode::OK);
    let doctor = body_json(doctor).await;
    let findings = doctor["findings"].as_array().expect("findings array");
    assert_eq!(findings.len(), 1);
    assert_eq!(findings[0]["kind"], serde_json::json!("claims_only"));
    assert_eq!(findings[0]["task_id"], serde_json::json!(orphan_task_id));
    assert_eq!(findings[0]["owner_id"], serde_json::json!("owner-1"));

    let missing_repository = app
        .clone()
        .oneshot(
            Request::builder()
                .uri("/api/v1/repositories/does-not-exist/work/doctor")
                .body(Body::empty())
                .expect("build unknown-repository request"),
        )
        .await
        .expect("serve Board Doctor route for an unknown repository");
    assert_eq!(missing_repository.status(), StatusCode::NOT_FOUND);
}
